/**
 * ResearchReport.tsx — Phase 4.3 Comprehensive Experiment Research Report.
 *
 * Research only — displays the deterministic, rule-based report generated by
 * the backend report engine. Never affects live or paper-trading strategy
 * selection. All values shown as N/A when unavailable (no NaN/undefined).
 */
import { useState, useEffect, useCallback } from "react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Loader2, RefreshCw, ChevronDown, ChevronRight, Download, FileText,
  FileSpreadsheet, AlertTriangle, FlaskConical, Play,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";
import { API_BASE, apiJson } from "@/lib/api";

/* eslint-disable @typescript-eslint/no-explicit-any */

const DISCLAIMER =
  "Research only — out-of-sample historical performance does not guarantee " +
  "future results. This report does not affect live or paper-trading strategy selection.";

// ── formatting: never render undefined/null/NaN/Infinity ───────────────────
function na(v: any, suffix = ""): string {
  if (v === null || v === undefined || v === "") return "N/A";
  if (typeof v === "number" && (!isFinite(v) || isNaN(v))) return "N/A";
  if (typeof v === "number") return `${+v.toFixed(2)}${suffix}`;
  if (typeof v === "boolean") return v ? "Yes" : "No";
  return String(v);
}

function reliabilityBadge(label?: string) {
  if (!label) return null;
  const cls: Record<string, string> = {
    "VERY LOW": "text-red-400 border-red-700",
    LOW: "text-amber-400 border-amber-700",
    LIMITED: "text-yellow-400 border-yellow-700",
    MODERATE: "text-sky-400 border-sky-700",
    STRONGER: "text-emerald-400 border-emerald-700",
  };
  return (
    <Badge variant="outline" className={cn("text-[9px] font-mono px-1", cls[label] ?? "text-zinc-400 border-zinc-600")}>
      {label}
    </Badge>
  );
}

function verdictColor(v?: string) {
  const s = String(v ?? "").toUpperCase();
  if (s.includes("PROMISING")) return "text-emerald-400 border-emerald-600 bg-emerald-500/10";
  if (s.includes("REJECT")) return "text-red-400 border-red-600 bg-red-500/10";
  if (s.includes("CONTINUE")) return "text-sky-400 border-sky-600 bg-sky-500/10";
  if (s.includes("INSUFFICIENT")) return "text-zinc-300 border-zinc-600 bg-zinc-500/10";
  return "text-amber-400 border-amber-600 bg-amber-500/10";
}

// ── generic table (horizontally scrollable on small screens) ────────────────
function T({ rows, cols, suffixes = {}, limit = 30 }: {
  rows: any[]; cols: [string, string][]; suffixes?: Record<string, string>; limit?: number;
}) {
  if (!rows || rows.length === 0) {
    return <p className="text-[10px] font-mono text-zinc-500">N/A — no data available.</p>;
  }
  return (
    <div className="overflow-x-auto">
      <table className="w-full text-[10px] font-mono">
        <thead>
          <tr className="text-zinc-500 border-b border-zinc-800">
            {cols.map(([k, l]) => <th key={k} className="text-left py-1 pr-3 whitespace-nowrap">{l}</th>)}
          </tr>
        </thead>
        <tbody>
          {rows.slice(0, limit).map((r, i) => (
            <tr key={i} className="border-b border-zinc-800/50">
              {cols.map(([k]) => (
                <td key={k} className="py-1 pr-3 text-zinc-300 whitespace-nowrap">
                  {k === "sample_label" || k === "reliability" || k === "evidence"
                    ? (reliabilityBadge(r[k]) ?? na(r[k]))
                    : na(r[k], suffixes[k] ?? "")}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {rows.length > limit && <p className="text-[9px] font-mono text-zinc-600 mt-1">Showing {limit} of {rows.length} rows — full data in CSV export.</p>}
    </div>
  );
}

const BREAKDOWN_COLS: [string, string][] = [
  ["group", "Group"], ["trades", "Trades"], ["win_rate", "Win%"],
  ["net_pnl", "Net P&L"], ["expectancy_rs", "Exp ₹"], ["profit_factor", "PF"],
  ["avg_return_pct", "Avg Ret%"], ["sample_label", "Evidence"],
];

// ── expandable section ───────────────────────────────────────────────────────
function Section({ title, children, defaultOpen = false, warn = 0 }: {
  title: string; children: React.ReactNode; defaultOpen?: boolean; warn?: number;
}) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="border border-zinc-800 rounded-md">
      <button className="w-full flex items-center gap-2 px-3 py-2 text-left" onClick={() => setOpen(o => !o)}>
        {open ? <ChevronDown className="h-3.5 w-3.5 text-zinc-500 flex-shrink-0" /> : <ChevronRight className="h-3.5 w-3.5 text-zinc-500 flex-shrink-0" />}
        <span className="text-[11px] font-mono font-semibold text-zinc-200">{title}</span>
        {warn > 0 && (
          <Badge variant="outline" className="text-[9px] font-mono text-amber-400 border-amber-700 px-1 ml-auto">
            <AlertTriangle className="h-2.5 w-2.5 mr-0.5" />{warn}
          </Badge>
        )}
      </button>
      {open && <div className="px-3 pb-3 space-y-2">{children}</div>}
    </div>
  );
}

function KV({ obj, keys }: { obj: any; keys: [string, string, string?][] }) {
  return (
    <div className="grid grid-cols-2 sm:grid-cols-4 gap-x-4 gap-y-1 text-[10px] font-mono">
      {keys.map(([k, l, suffix]) => (
        <div key={k}><span className="text-zinc-500">{l} </span><span className="text-zinc-200">{na(obj?.[k], suffix ?? "")}</span></div>
      ))}
    </div>
  );
}

function Warnings({ list }: { list?: string[] }) {
  if (!list || list.length === 0) return null;
  return (
    <div className="space-y-1">
      {list.map((w, i) => (
        <div key={i} className="text-[10px] font-mono text-amber-400 bg-amber-500/10 border border-amber-500/30 rounded px-2 py-1">{w}</div>
      ))}
    </div>
  );
}

// ── next-experiment card with preview + confirm-to-queue ────────────────────
function NextExperimentCard({ sug, expId, onQueued }: { sug: any; expId: string; onQueued: () => void }) {
  const { toast } = useToast();
  const [preview, setPreview] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const [queuing, setQueuing] = useState(false);

  async function queue() {
    setQueuing(true);
    try {
      await apiJson(`/experiments/${expId}/suggested-experiments/${sug.id}/queue`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ confirm: true }),
      });
      toast({ title: "Experiment queued", description: `"${sug.name}" added to the queue.` });
      setConfirming(false);
      onQueued();
    } catch (e) {
      toast({ title: "Queue failed", description: String(e), variant: "destructive" });
    } finally { setQueuing(false); }
  }

  return (
    <div className="border border-zinc-800 rounded p-2 space-y-1.5">
      <div className="flex items-center gap-2 flex-wrap">
        <Badge variant="outline" className={cn("text-[9px] font-mono px-1",
          sug.priority === "HIGH" ? "text-red-400 border-red-700" : sug.priority === "MEDIUM" ? "text-amber-400 border-amber-700" : "text-zinc-400 border-zinc-600")}>
          {na(sug.priority)}
        </Badge>
        <span className="text-[11px] font-mono font-semibold text-zinc-200">{na(sug.name)}</span>
        <div className="ml-auto flex gap-1">
          <Button size="sm" variant="outline" className="h-6 px-2 font-mono text-[10px]" onClick={() => setPreview(p => !p)}>
            Preview
          </Button>
          <Button size="sm" className="h-6 px-2 font-mono text-[10px] bg-violet-600 hover:bg-violet-500 text-white" onClick={() => setConfirming(true)}>
            <Play className="h-3 w-3 mr-1" />Queue
          </Button>
          <AlertDialog open={confirming} onOpenChange={setConfirming}>
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle className="font-mono text-sm">Queue suggested experiment?</AlertDialogTitle>
                <AlertDialogDescription className="font-mono text-xs">
                  "{na(sug.name)}" will be added to the experiment queue as a new
                  research experiment. It will not run automatically and will not
                  affect live or paper-trading strategy selection.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel className="font-mono text-xs">Cancel</AlertDialogCancel>
                <AlertDialogAction className="font-mono text-xs bg-emerald-600 hover:bg-emerald-500 text-white"
                  onClick={(e) => { e.preventDefault(); queue(); }} disabled={queuing}>
                  {queuing ? <Loader2 className="h-3 w-3 animate-spin" /> : "Confirm & Queue"}
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      </div>
      <p className="text-[10px] font-mono text-zinc-400">{na(sug.hypothesis)}</p>
      <p className="text-[9px] font-mono text-zinc-500">Variable: {na(sug.primary_variable)} · Sample target: {na(sug.required_sample_target)} · {na(sug.rationale)}</p>
      {preview && (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-[9px] font-mono">
          <div className="bg-zinc-900/60 border border-zinc-800 rounded p-2">
            <p className="text-zinc-500 mb-1">CONTROL</p>
            <pre className="text-zinc-300 whitespace-pre-wrap">{JSON.stringify(sug.control_config ?? {}, null, 1)}</pre>
          </div>
          <div className="bg-zinc-900/60 border border-violet-800/50 rounded p-2">
            <p className="text-violet-400 mb-1">TREATMENT</p>
            <pre className="text-zinc-300 whitespace-pre-wrap">{JSON.stringify(sug.treatment_config ?? {}, null, 1)}</pre>
          </div>
          <div className="sm:col-span-2 text-zinc-500">
            Success: {na(sug.success_criteria)} · Rejection: {na(sug.rejection_criteria)}
          </div>
        </div>
      )}
    </div>
  );
}

// ── main component ───────────────────────────────────────────────────────────
export function ResearchReport({ expId, onQueued }: { expId: string; onQueued?: () => void }) {
  const { toast } = useToast();
  const [status, setStatus] = useState<any>(null);
  const [report, setReport] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const st = await apiJson(`/experiments/${expId}/report/status`);
      setStatus(st);
      if (st.latest_completed_version) {
        const rep = await apiJson(`/experiments/${expId}/report`);
        setReport(rep.report);
      } else {
        setReport(null);
      }
    } catch (e: any) {
      if (e?.status === 404) { setStatus({ status: "NONE" }); setReport(null); }
      else setError(String(e?.message ?? e));
    } finally { setLoading(false); }
  }, [expId]);

  useEffect(() => { load(); }, [load]);

  async function generate(force: boolean) {
    setGenerating(true);
    try {
      const r = await apiJson(`/experiments/${expId}/report/${force ? "regenerate" : "generate"}`, { method: "POST" });
      toast({ title: r.skipped ? "Report unchanged" : "Report generated", description: r.skipped ? "Source results have not changed." : `Version ${r.version} ready.` });
      await load();
    } catch (e) {
      toast({ title: "Report generation failed", description: String(e), variant: "destructive" });
      await load();
    } finally { setGenerating(false); }
  }

  const dispStatus = generating ? "GENERATING" : (status?.status ?? "NONE");
  const badgeCls: Record<string, string> = {
    GENERATING: "text-sky-400 border-sky-600 animate-pulse",
    COMPLETED: "text-emerald-400 border-emerald-600",
    FAILED: "text-red-400 border-red-600",
    OUTDATED: "text-amber-400 border-amber-600",
    NONE: "text-zinc-400 border-zinc-600",
  };
  const badgeLabel: Record<string, string> = {
    GENERATING: "Generating", COMPLETED: "Ready", FAILED: "Failed",
    OUTDATED: "Outdated", NONE: "Not generated",
  };

  if (loading) {
    return <div className="flex items-center gap-2 text-[11px] font-mono text-zinc-500 py-3"><Loader2 className="h-3.5 w-3.5 animate-spin" />Loading research report…</div>;
  }

  const es = report?.executive_summary ?? {};
  const perf = report?.performance_analysis ?? {};
  const risk = report?.risk_analysis ?? {};
  const dist = report?.trade_distribution?.tables ?? {};
  const conf = report?.confidence_analysis ?? {};
  const fps = report?.false_positive_analysis ?? {};
  const missed = report?.missed_opportunity_analysis ?? {};
  const feats = report?.feature_analysis ?? {};
  const params = report?.parameter_sensitivity ?? {};
  const regimes = report?.regime_analysis ?? {};
  const holding = report?.holding_period_analysis ?? {};
  const dd = report?.drawdown_analysis ?? {};
  const examples = report?.trade_examples ?? {};
  const fv = report?.final_verdict ?? {};
  const diag = report?.diagnostics ?? {};

  const tradeCols: [string, string][] = [
    ["symbol", "Stock"], ["strategy_name", "Strategy"], ["entry_date", "Entry"],
    ["exit_date", "Exit"], ["return_pct", "Ret%"], ["net_pnl", "Net ₹"],
    ["confidence", "Conf"], ["market_regime", "Regime"], ["exit_reason", "Exit Reason"],
    ["mae_pct", "MAE%"], ["mfe_pct", "MFE%"], ["holding_days", "Days"],
  ];

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 flex-wrap">
        <FlaskConical className="h-3.5 w-3.5 text-violet-400" />
        <span className="text-[11px] font-mono font-semibold text-zinc-200">Research Report</span>
        <Badge variant="outline" className={cn("text-[9px] font-mono px-1.5", badgeCls[dispStatus] ?? badgeCls.NONE)}>
          {badgeLabel[dispStatus] ?? dispStatus}
        </Badge>
        {report && <span className="text-[9px] font-mono text-zinc-600">v{na(report.report_version)} · {String(report.generated_at ?? "").slice(0, 16).replace("T", " ")}</span>}
        <div className="ml-auto flex gap-1 flex-wrap">
          {report && (
            <>
              <a href={`${API_BASE}/experiments/${expId}/report/export/json`} download>
                <Button size="sm" variant="outline" className="h-6 px-2 font-mono text-[10px]"><Download className="h-3 w-3 mr-1" />JSON</Button>
              </a>
              <a href={`${API_BASE}/experiments/${expId}/report/export/csv`} download>
                <Button size="sm" variant="outline" className="h-6 px-2 font-mono text-[10px]"><FileSpreadsheet className="h-3 w-3 mr-1" />CSV</Button>
              </a>
              <a href={`${API_BASE}/experiments/${expId}/report/export/html`} target="_blank" rel="noreferrer">
                <Button size="sm" variant="outline" className="h-6 px-2 font-mono text-[10px]"><FileText className="h-3 w-3 mr-1" />Print</Button>
              </a>
            </>
          )}
          <Button size="sm" className="h-6 px-2 font-mono text-[10px] bg-violet-600 hover:bg-violet-500 text-white"
            onClick={() => generate(dispStatus === "COMPLETED" || dispStatus === "OUTDATED")} disabled={generating}>
            {generating ? <Loader2 className="h-3 w-3 mr-1 animate-spin" /> : <RefreshCw className="h-3 w-3 mr-1" />}
            {dispStatus === "NONE" || dispStatus === "FAILED" ? (dispStatus === "FAILED" ? "Retry report generation" : "Generate") : "Regenerate"}
          </Button>
        </div>
      </div>

      <p className="text-[9px] font-mono text-amber-400/90 bg-amber-500/5 border border-amber-500/20 rounded px-2 py-1">{DISCLAIMER}</p>

      {error && <div className="text-[10px] font-mono text-red-400 bg-red-500/10 border border-red-500/30 rounded px-2 py-1.5">{error}</div>}
      {dispStatus === "FAILED" && status?.error && (
        <div className="text-[10px] font-mono text-red-400 bg-red-500/10 border border-red-500/30 rounded px-2 py-1.5">Last generation failed: {status.error}</div>
      )}
      {!report && dispStatus !== "FAILED" && !error && (
        <p className="text-[10px] font-mono text-zinc-500">No research report yet. Click Generate to build one from the stored experiment results.</p>
      )}

      {report && (
        <div className="space-y-1.5">
          <Section title="1 · Research Verdict" defaultOpen>
            <div className={cn("inline-block border rounded px-2 py-1 text-[11px] font-mono font-bold", verdictColor(fv.verdict))}>{na(fv.verdict)}</div>
            <ul className="space-y-0.5">
              {(fv.reasons ?? []).map((r: string, i: number) => <li key={i} className="text-[10px] font-mono text-zinc-400">• {r}</li>)}
            </ul>
            <p className="text-[9px] font-mono text-zinc-600">{na(fv.disclaimer)}</p>
          </Section>

          <Section title="2 · Executive Summary" defaultOpen>
            <p className="text-[10px] font-mono text-zinc-300">{na(es.explanation)}</p>
            <KV obj={es} keys={[["oos_trades", "Trades"], ["windows", "Windows"], ["net_return_pct", "Net Ret", "%"], ["net_pnl", "Net P&L ₹"], ["profit_factor", "PF"], ["expectancy_rs", "Exp ₹"], ["win_rate", "Win%", "%"], ["sharpe", "Sharpe"], ["max_drawdown_pct", "Max DD", "%"], ["total_costs", "Costs ₹"], ["evidence_verdict", "Evidence"], ["score", "Score"]]} />
            {(es.overfitting_flags ?? []).length > 0 && <Warnings list={es.overfitting_flags.map((f: string) => `Overfitting flag: ${f}`)} />}
          </Section>

          <Section title="3 · Performance">
            <KV obj={perf} keys={[["gross_pnl", "Gross P&L ₹"], ["net_pnl", "Net P&L ₹"], ["total_costs", "Costs ₹"], ["cost_drag_pct_of_gross_profit", "Cost Drag", "%"], ["profit_factor", "PF"], ["expectancy_rs", "Exp ₹"], ["win_rate", "Win%", "%"], ["avg_win", "Avg Win ₹"], ["avg_loss", "Avg Loss ₹"], ["median_win", "Med Win ₹"], ["median_loss", "Med Loss ₹"], ["payoff_ratio", "Payoff"], ["sharpe", "Sharpe"], ["sortino", "Sortino"], ["calmar", "Calmar"], ["recovery_factor", "Recovery"], ["turnover", "Turnover"], ["exposure_pct", "Exposure", "%"], ["avg_holding_days", "Avg Hold d"], ["median_holding_days", "Med Hold d"], ["max_consecutive_wins", "Max Win Streak"], ["max_consecutive_losses", "Max Loss Streak"], ["pct_profitable_windows", "Profitable Windows", "%"]]} />
            <p className="text-[10px] font-mono text-zinc-500 mt-1">Benchmarks (net):</p>
            <KV obj={perf.benchmarks} keys={[["strategy_net_return_pct", "Strategy", "%"], ["nifty_buy_hold_pct", "NIFTY 50", "%"], ["equal_weight_universe_pct", "Equal-Weight", "%"], ["cash_pct", "Cash", "%"], ["base_model_pct", "Base Model", "%"]]} />
            <T rows={perf.windows ?? []} cols={[["window", "Window"], ["trades", "Trades"], ["net_return_pct", "Net%"], ["profit_factor", "PF"], ["win_rate", "Win%"], ["max_drawdown_pct", "DD%"]]} />
          </Section>

          <Section title="4 · Risk" warn={(risk.warnings ?? []).length}>
            <KV obj={risk} keys={[["max_drawdown_pct", "Max DD", "%"], ["avg_drawdown_pct", "Avg DD", "%"], ["longest_drawdown_days", "Longest DD d"], ["time_underwater_pct", "Underwater", "%"], ["largest_single_trade_loss", "Worst Trade ₹"], ["p5_trade_return_pct", "P5 Ret", "%"], ["p95_trade_return_pct", "P95 Ret", "%"], ["downside_deviation_pct", "Downside Dev", "%"], ["risk_of_ruin_estimate_pct", "Ruin Est", "%"], ["top5_trades_profit_share_pct", "Top5 Profit Share", "%"], ["top5_losses_share_pct", "Top5 Loss Share", "%"], ["depends_on_few_trades", "Few-Trade Dependent"]]} />
            <p className="text-[9px] font-mono text-zinc-600">{na(risk.risk_of_ruin_note)}</p>
            <Warnings list={risk.warnings} />
          </Section>

          <Section title="5 · Equity & Drawdown">
            <T rows={dd.episodes ?? []} cols={[["start_date", "Start"], ["trough_date", "Trough"], ["recovery_date", "Recovered"], ["depth_pct", "Depth%"], ["duration_days", "Days"], ["trades_during", "Trades"], ["dominant_strategy", "Dominant Strategy"], ["dominant_regime", "Regime"]]} />
            {dd.largest_drawdown_explanation && <p className="text-[10px] font-mono text-zinc-400">{dd.largest_drawdown_explanation}</p>}
            <p className="text-[9px] font-mono text-zinc-600">Full equity and drawdown curves are included in the JSON export.</p>
          </Section>

          <Section title="6 · Trade Distribution">
            {Object.entries(dist).map(([name, rows]: [string, any]) => (
              (rows ?? []).length > 0 && (
                <div key={name}>
                  <p className="text-[10px] font-mono text-zinc-500 mt-1 uppercase">{name.replace(/_/g, " ")}</p>
                  <T rows={rows} cols={BREAKDOWN_COLS} limit={12} />
                </div>
              )
            ))}
            {(report.trade_distribution?.notes ?? []).map((n: string, i: number) => <p key={i} className="text-[9px] font-mono text-zinc-600">{n}</p>)}
          </Section>

          <Section title="7 · Confidence Calibration" warn={(conf.warnings ?? []).length}>
            <div className="grid grid-cols-2 gap-2">
              <div>
                <p className="text-[10px] font-mono text-zinc-500">BEFORE calibration</p>
                <KV obj={conf.before_calibration} keys={[["brier_score", "Brier"], ["ece", "ECE"], ["log_loss", "LogLoss"]]} />
              </div>
              <div>
                <p className="text-[10px] font-mono text-zinc-500">AFTER calibration</p>
                <KV obj={conf.after_calibration} keys={[["brier_score", "Brier"], ["ece", "ECE"], ["log_loss", "LogLoss"]]} />
              </div>
            </div>
            <KV obj={conf} keys={[["samples", "Samples"], ["method", "Method"], ["high_confidence_losses", "High-Conf Losses"], ["low_confidence_winners", "Low-Conf Winners"]]} />
            <T rows={conf.reliability_buckets ?? []} cols={[["range", "Bucket"], ["count", "N"], ["predicted_win_prob", "Predicted"], ["actual_win_rate", "Actual"], ["gap", "Gap"]]} />
            <T rows={conf.negative_expectancy_bands ?? []} cols={[["band", "Conf Band"], ["trades", "Trades"], ["expectancy_rs", "Exp ₹"], ["sample_label", "Evidence"]]} />
            <Warnings list={conf.warnings} />
          </Section>

          <Section title="8 · False Positives">
            <p className="text-[10px] font-mono text-zinc-400">{na(fps.definition)}</p>
            <KV obj={fps} keys={[["count", "Count"], ["total_trades", "Of Trades"], ["rate_pct", "Rate", "%"], ["avg_mae_pct", "Avg MAE", "%"], ["avg_mfe_pct", "Avg MFE", "%"], ["avg_holding_days", "Avg Hold d"]]} />
            <T rows={fps.subgroup_rates ?? []} cols={[["dimension", "Dimension"], ["group", "Group"], ["sample_count", "N"], ["baseline_rate_pct", "Base%"], ["subgroup_rate_pct", "Group%"], ["abs_difference_pct", "Diff%"], ["reliability", "Evidence"]]} />
            <p className="text-[9px] font-mono text-zinc-600">{na(fps.language_note)}</p>
          </Section>

          <Section title="9 · Missed Opportunities">
            {missed.available === false ? (
              <p className="text-[10px] font-mono text-zinc-500">{na(missed.note)}</p>
            ) : (
              <>
                <T rows={missed.categories ?? []} cols={[["category", "Category"], ["cases", "Cases"], ["avg_fwd_5d_pct", "Fwd 5d%"], ["avg_fwd_10d_pct", "Fwd 10d%"], ["avg_fwd_20d_pct", "Fwd 20d%"], ["avg_mfe_pct", "MFE%"], ["avg_mae_pct", "MAE%"], ["avg_confidence", "Conf"], ["reliability", "Evidence"]]} />
                {missed.watch_that_rose && <KV obj={missed.watch_that_rose} keys={[["watch_signals", "WATCH Signals"], ["rose_over_3pct_in_10d", "Rose >3% in 10d"], ["share_pct", "Share", "%"]]} />}
                <p className="text-[9px] font-mono text-zinc-600">{na(missed.note)}</p>
              </>
            )}
          </Section>

          <Section title="10 · Feature Analysis">
            <T rows={feats.features ?? []} cols={[["feature", "Feature"], ["samples", "N"], ["winner_mean", "Winner Avg"], ["loser_mean", "Loser Avg"], ["winner_loser_gap", "Gap"], ["windows_consistent", "Consistent Win."], ["windows_total", "Windows"], ["assessment", "Assessment"], ["sample_label", "Evidence"]]} />
            <p className="text-[9px] font-mono text-zinc-600">{na(feats.note)}</p>
          </Section>

          <Section title="11 · Parameter Sensitivity">
            {Object.entries(params.sweeps ?? {}).map(([name, rows]: [string, any]) => (
              <div key={name}>
                <p className="text-[10px] font-mono text-zinc-500 mt-1 uppercase">{name.replace(/_/g, " ")}</p>
                <T rows={rows ?? []} cols={Object.keys((rows ?? [])[0] ?? {}).slice(0, 8).map(k => [k, k]) as [string, string][]} limit={12} />
              </div>
            ))}
            {(params.highlights ?? []).map((h: any, i: number) => (
              <div key={i} className="text-[10px] font-mono text-sky-400 bg-sky-500/10 border border-sky-500/30 rounded px-2 py-1">{h.message}</div>
            ))}
            <p className="text-[9px] font-mono text-zinc-600">{na(params.note)}</p>
          </Section>

          <Section title="12 · Market Regimes">
            <T rows={regimes.tables ?? []} cols={[...BREAKDOWN_COLS, ["pct_of_trades", "%Trades"], ["pct_of_net_pnl", "%P&L"]]} />
            <p className="text-[10px] font-mono text-zinc-500">Eligibility (analysis only):</p>
            <T rows={regimes.eligibility_recommendations ?? []} cols={[["regime", "Regime"], ["recommendation", "Recommendation"], ["trades", "Trades"], ["expectancy_rs", "Exp ₹"], ["sample_label", "Evidence"]]} />
            <p className="text-[9px] font-mono text-amber-400/80">{na(regimes.disclaimer)}</p>
          </Section>

          <Section title="13 · Holding Periods">
            <T rows={holding.tables ?? []} cols={[...BREAKDOWN_COLS, ["avg_mae_pct", "MAE%"], ["avg_mfe_pct", "MFE%"]]} />
            <p className="text-[10px] font-mono text-zinc-500">Controlled alternative-exit analysis:</p>
            <T rows={holding.alternative_exits ?? []} cols={[["exit_after_days", "Exit After"], ["trades", "Trades"], ["avg_return_pct", "Avg Ret%"], ["win_rate", "Win%"], ["sample_label", "Evidence"]]} />
            <p className="text-[9px] font-mono text-zinc-600">{na(holding.alternative_exit_note)}</p>
          </Section>

          <Section title="14 · Best & Worst Trades">
            {([["top_winners", "Top winners"], ["top_losers", "Top losers"], ["highest_mae", "Highest MAE"], ["high_confidence_losses", "High-confidence losses"], ["low_confidence_winners", "Low-confidence winners"]] as [string, string][]).map(([k, l]) => (
              (examples[k] ?? []).length > 0 && (
                <div key={k}>
                  <p className="text-[10px] font-mono text-zinc-500 mt-1 uppercase">{l}</p>
                  <T rows={examples[k]} cols={tradeCols} limit={10} />
                </div>
              )
            ))}
          </Section>

          <Section title="15 · Strengths">
            {(report.strengths ?? []).length === 0 && <p className="text-[10px] font-mono text-zinc-500">N/A — no strengths identified.</p>}
            {(report.strengths ?? []).map((s: any, i: number) => (
              <div key={i} className="text-[10px] font-mono text-zinc-300 border-l-2 border-emerald-700 pl-2">
                <span className="font-semibold">{s.title}</span> — {s.explanation} <span className="text-zinc-500">({s.supporting_metric}, n={na(s.sample_count)})</span> {reliabilityBadge(s.reliability)}
              </div>
            ))}
          </Section>

          <Section title="16 · Weaknesses" warn={(report.weaknesses ?? []).length}>
            {(report.weaknesses ?? []).length === 0 && <p className="text-[10px] font-mono text-zinc-500">N/A — no weaknesses identified.</p>}
            {(report.weaknesses ?? []).map((w: any, i: number) => (
              <div key={i} className="text-[10px] font-mono text-zinc-300 border-l-2 border-red-800 pl-2">
                <span className="font-semibold">{w.title}</span> — {w.explanation} <span className="text-zinc-500">({w.supporting_metric}, n={na(w.sample_count)})</span> {reliabilityBadge(w.reliability)}
              </div>
            ))}
          </Section>

          <Section title="17 · Recommendations">
            <T rows={report.recommendations ?? []} cols={[["priority", "Priority"], ["category", "Category"], ["action", "Action"], ["reason", "Reason"], ["risk", "Risk"], ["may_affect_live_logic", "Affects Live?"]]} />
          </Section>

          <Section title="18 · Suggested Next Experiments">
            {(report.next_experiments?.suggestions ?? []).map((s: any) => (
              <NextExperimentCard key={s.id} sug={s} expId={expId} onQueued={() => onQueued?.()} />
            ))}
            <p className="text-[9px] font-mono text-zinc-600">{na(report.next_experiments?.note)}</p>
          </Section>

          <Section title="19 · Diagnostics">
            <KV obj={diag} keys={[["source_trade_count", "Source Trades"], ["variant_c_trades_used", "Used (Variant C)"], ["duplicate_rows_removed", "Dupes Removed"], ["invalid_rows_ignored", "Invalid Ignored"], ["ledger_rows", "Ledger Rows"], ["windows_used", "Windows"], ["generation_seconds", "Gen Time s"]]} />
            <KV obj={diag.lookahead_audit} keys={[["decisions_logged", "Decisions Logged"], ["violations", "Lookahead Violations"], ["status", "Audit Status"]]} />
            {(diag.missing_sources ?? []).length > 0 && <Warnings list={diag.missing_sources.map((m: string) => `Missing source: ${m}`)} />}
            <p className="text-[9px] font-mono text-zinc-600">Intrabar rule: {na(diag.intrabar_rule)} · Boundaries: {na(diag.date_boundaries?.start)} → {na(diag.date_boundaries?.end)} · Hash: {na(report.source_result_hash)}</p>
          </Section>
        </div>
      )}
    </div>
  );
}
